function test_base64_to_binary() {
    $exchange = new \ccxt\async\Exchange(array(
        'id' => 'sampleexchange',
    ));
    // @SKIP_START_GO
    // every sample must survive base64 -> binary -> base64 unchanged
    $samples = ['aGVsbG8=', 'aGVsbG8gd29ybGQ=', 'dGVzdA==', '', 'YQ==', 'YWI=', 'YWJj', 'eyJrZXkiOiJ2YWx1ZSJ9', 'MTIzNDU2', 'aGVsbG8rd29ybGQvdGVzdA=='];
    for ($i = 0; $i < count($samples); $i++) {
        $sample = $samples[$i];
        $binary = $exchange->base64_to_binary($sample);
        assert($exchange->binary_to_base64($binary) === $sample, 'base64 round-trip failed for ' . $sample);
    }
    // @SKIP_END_GO
    assert($exchange->safe_string(null, 'key') === null, 'GO_WORKAROUND');
}
